def transform(grid: list[list[int]]) -> list[list[int]]:
    """
    The transformation rule is based on the positions of the value 3 in the input grid.
    1. Identify all coordinates (rs, cs) where grid[rs][cs] == 3.
    2. For every cell (r, c) in the grid, count how many such seeds (rs, cs) satisfy 
       the condition that the seed is to the right and/or below the current cell 
       (i.e., r <= rs and c <= cs).
    3. If the count is 0, the output cell is 0.
    4. If the count is even and greater than 0, the output cell is 3.
    5. If the count is odd, the output cell is 9.
    """
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    # Find all seeds (cells with value 3)
    seeds = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                seeds.append((r, c))

    # Create the output grid
    output = [[0 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            count = 0
            for rs, cs in seeds:
                if r <= rs and c <= cs:
                    count += 1

            if count == 0:
                output[r][c] = 0
            elif count % 2 == 0:
                output[r][c] = 3
            else:
                output[r][c] = 9

    return output
